let (tx, mut rx) = mpsc::channel::<Change>(1024);
// producers: tx.send(change).await?;
let mut tick = tokio::time::interval(Duration::from_millis(200));
loop {
    tokio::select! {
        _ = tick.tick() => {}
        Some(c) = rx.recv() => { dirty.insert(c.key, c.row); }
    }
    if dirty.is_empty() { continue; }
    let batch = std::mem::take(&mut dirty);   // one row per key
    let mut tx = pool.begin().await?;
    for (k, r) in batch { query(UPSERT).bind(r).bind(k).execute(&mut *tx).await?; }
    tx.commit().await?;
}
